pub fn handle_fps(
    ineffable: Res<Ineffable>,
    active_mapping: Res<ActiveMappingConfig>,
    cs_tx_res: Res<ChannelSenderCS>,
    script_command_tx: Res<ScriptRuntimeCommandSender>,
    shared_state: Res<ScriptSharedState>,
    mut fps_config: ResMut<ActiveCursorFpsConfig>,
    mut active_fire_map: ResMut<ActiveFireMap>,
    mapping_state: Res<State<MappingState>>,
    state: Res<State<CursorState>>,
    mut next_state: ResMut<NextState<CursorState>>,
    cursor_pos: Res<CursorPosition>,
    mask_size: Res<MaskSize>,
    runtime: ResMut<TokioTasksRuntime>,
) {
    if let Some(active_mapping) = &active_mapping.0 {
        for (action, mapping) in &active_mapping.mappings {
            if action.as_ref().starts_with("Fps") {
                if ineffable.just_pulsed(action.ineff_pulse()) {
                    let original_size: Vec2 = active_mapping.original_size.into();
                    match state.get() {
                        CursorState::Normal => {
                            let mapping = mapping.as_ref_fps();
                            if let Some(interaction) = mapping.interaction
                                && let Some(position) = interaction.close_position
                            {
                                send_interaction_tap(
                                    &cs_tx_res.0,
                                    interaction.pointer_id,
                                    original_size,
                                    position,
                                );
                            }
                            enter_fps_mode(
                                &cs_tx_res.0,
                                &mut fps_config,
                                &mut next_state,
                                mapping,
                                original_size,
                            );
                        }
                        CursorState::Fps => {
                            let interaction = mapping.as_ref_fps().interaction;
                            let released_fire_actions = exit_fps_mode(
                                &cs_tx_res.0,
                                &mut fps_config,
                                &mut active_fire_map,
                                &mut next_state,
                                mask_size.0,
                                cursor_pos.0,
                            );
                            spawn_fire_after_hooks_for_external_release(
                                released_fire_actions,
                                active_mapping,
                                &cs_tx_res,
                                &script_command_tx,
                                &shared_state,
                                &runtime,
                                cursor_pos.0,
                                mask_size.0,
                                mapping_state.get() == &MappingState::RawInput,
                                true,
                            );
                            if let Some(interaction) = interaction {
                                send_interaction_tap(
                                    &cs_tx_res.0,
                                    interaction.pointer_id,
                                    original_size,
                                    interaction.open_position,
                                );
                            }
                        }
                    };
                    return;
                }
            }
        }
    }
}

